using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new AIToolCollection
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
            // Simulated web search results for demonstration
            return $"Search results for '{query}': " +
                "1. Recent advances show significant progress in this area. " +
                "2. Experts highlight key challenges and opportunities. " +
                "3. Industry adoption is accelerating with new frameworks.";
        },
        "web_search",
        "Searches the web for information on a given query. Returns a summary of top results."),
    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [Notes] Saved note: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),
    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all saved research notes to review findings so far."),
};

var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Using the web_search tool to find relevant information (search multiple angles).
        2. Using the take_note tool to save key findings as structured notes.
        3. Using get_notes to review what you've gathered.
        4. Finally, provide a comprehensive summary of your research findings.

        Be thorough — perform at least 3 searches from different angles before summarizing.
        """,
};

Console.WriteLine("═══════════════════════════════════════════");
Console.WriteLine("  Research Agent (powered by GPT-4o-mini)");
Console.WriteLine("═══════════════════════════════════════════");
Console.Write("\nEnter a research topic: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: \"{topic}\"\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = tools,
    ChatOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 2048,
    },
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n───────────────────────────────────────────");
Console.WriteLine("Research complete. Notes saved:");
Console.WriteLine("───────────────────────────────────────────");
foreach (var note in noteService.GetAllNotes())
{
    Console.WriteLine($"  • {note.Title}");
}
Console.WriteLine();

