arguments.new_str:
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient());

builder.Services.AddSingleton<NoteService>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteService = host.Services.GetRequiredService<NoteService>();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            Console.WriteLine($"  [WebSearch] Searching: \"{query}\"");
            // Simulated web search — replace with a real search API (e.g., Bing Search)
            return $"Search results for '{query}': " +
                "1. Recent advances show significant progress in this area. " +
                "2. Experts highlight key challenges and opportunities. " +
                "3. Industry adoption is accelerating with new frameworks.";
        },
        "web_search",
        "Searches the web for information on a given query. Returns a summary of top results."),
    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            noteService.AddNote(title, content);
            Console.WriteLine($"  [Notes] Saved note: \"{title}\"");
            return $"Note '{title}' saved successfully.";
        },
        "take_note",
        "Saves a research note with a title and content for later reference."),
    AIFunctionFactory.Create(
        () =>
        {
            var notes = noteService.GetAllNotes();
            return notes.Count == 0
                ? "No notes saved yet."
                : string.Join("\n\n", notes.Select(n => $"## {n.Title}\n{n.Content}"));
        },
        "get_notes",
        "Retrieves all saved research notes to review findings so far."),
};

var agent = new ChatClientAgent(chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Using the web_search tool to find relevant information (search multiple angles).
        2. Using the take_note tool to save key findings as structured notes.
        3. Using get_notes to review what you've gathered.
        4. Finally, provide a comprehensive summary of your research findings.

